{"q": 17577, "quiz": 1244, "obj": "P1.COMPETITOR", "kind": "mcq", "was": "sentence", "body": "What do Earth and the other planets move around?", "why": "في النص أجرام عدّة تتنافس، والمطلوب ما تدور حوله الكواكب: «Like the sun. It pulls Earth and the other planets, and makes them move around it.»", "opts": [{"t": "A star far away.", "dx": "MIX", "key": false}, {"t": "The sun.", "dx": null, "key": true}, {"t": "Jupiter.", "dx": "MIX", "key": false}, {"t": "The moon.", "dx": "MIX", "key": false}]},
{"q": 17578, "quiz": 1244, "obj": "P2.ACROSS_PARA", "kind": "mcq", "was": "sentence", "body": "Jupiter has more mass than the moon. Why is its pull on us weaker?", "why": "الدليل في فقرتين متتاليتين: القمر «close enough to pull the water in our oceans and create tides.» ثم في التالية «the farther the object, the lesser its pull.» والمشتري «so far away».", "opts": [{"t": "Jupiter is lighter than the moon.", "dx": "REV", "key": false}, {"t": "Jupiter is very far away from us.", "dx": null, "key": true}, {"t": "Jupiter has no gravity at all.", "dx": "JUMP", "key": false}, {"t": "Jupiter has no oceans or water.", "dx": "GAP", "key": false}]},
{"q": 17579, "quiz": 1244, "obj": "P2.WORD_CONTEXT", "kind": "mcq", "was": "sentence", "body": "Earth says, \"greater the mass, stronger the pull.\" What is \"mass\"?", "why": "المعنى من الجملة التالية للكلمة مباشرة: «Mass is the amount of matter or stuff in an object.»", "opts": [{"t": "The space around a planet.", "dx": null, "key": false}, {"t": "The pull of the moon on the oceans.", "dx": "MIX", "key": false}, {"t": "The amount of stuff in an object.", "dx": null, "key": true}, {"t": "The way from Earth to the moon.", "dx": "MIX", "key": false}]},
{"q": 17580, "quiz": 1244, "obj": "P3.MAIN_PARA", "kind": "mcq", "was": "sentence", "body": "Read the paragraph that starts with \"Earth sighs and explains\". What is this paragraph about?", "why": "فكرة الفقرة في جملتيها: «Gravity is an invisible force that makes everything, and I mean EVERYTHING, around us pull or attract each other. It keeps all things in order.»", "opts": [{"t": "How a rocket takes off to the moon.", "dx": "MIX", "key": false}, {"t": "How gravity pulls things and keeps them in order.", "dx": null, "key": true}, {"t": "Why Aru wants to fly like a superhero.", "dx": "MIX", "key": false}, {"t": "How the moon makes tides in the oceans.", "dx": "MIX", "key": false}]},
{"q": 17581, "quiz": 1244, "obj": "P3.CHANGE", "kind": "mcq", "was": "sentence", "body": "How does Aru change from the start of the story to the end?", "why": "التغيّر بين أول القصة وآخرها: صرخت أولاً «Gravity, I haaaate you!» ثم قالت بعد خطة الأرض «Now can you please turn gravity back on again?»", "opts": [{"t": "First she hates gravity. At the end she asks for it back.", "dx": null, "key": true}, {"t": "First she wants to fly. At the end she is afraid of planes.", "dx": "JUMP", "key": false}, {"t": "First she loves gravity. At the end she hates it.", "dx": "REV", "key": false}, {"t": "First she is angry with Earth. At the end she is angry with Ma.", "dx": "JUMP", "key": false}]},
{"q": 20823, "quiz": 1786, "obj": "P1.COMPETITOR", "kind": "mcq", "was": "sentence", "body": "How long did Armstrong and Aldrin work outside their spacecraft on the moon?", "why": "في النص مدّتان تتنافسان، والمطلوب مدّة العمل خارج المركبة: «Armstrong and Aldrin spent more than two-and-a-half hours working outside their spacecraft on the moon.» أما «21-and-a-half hours» فمدّة البقاء كلها.", "opts": [{"t": "More than two-and-a-half hours.", "dx": null, "key": true}, {"t": "21-and-a-half hours.", "dx": "MIX", "key": false}, {"t": "More than 40 years.", "dx": "MIX", "key": false}, {"t": "About 13 hours.", "dx": null, "key": false}]},
{"q": 20824, "quiz": 1786, "obj": "P2.WORD_CONTEXT", "kind": "mcq", "was": "sentence", "body": "Armstrong went to work for \"NACA\" in 1955. What was NACA?", "why": "المعنى من الجملة التالية للاسم: «NACA was a government agency that researched airplanes.»", "opts": [{"t": "A government agency that researched airplanes.", "dx": null, "key": true}, {"t": "A college for the U.S. Navy.", "dx": "MIX", "key": false}, {"t": "A rocket plane with records for speed.", "dx": "MIX", "key": false}, {"t": "A spacecraft with no crew inside.", "dx": "MIX", "key": false}]},
{"q": 20825, "quiz": 1786, "obj": "P2.ACROSS_PARA", "kind": "mcq", "was": "sentence", "body": "Armstrong said, \"That's one small step for (a) man.\" What step is this?", "why": "الدليل في فقرتين متتاليتين: تنتهي الأولى بـ«Armstrong took the first step on the moon.» وتبدأ التالية بقوله «That's one small step for (a) man; one giant leap for mankind.»", "opts": [{"t": "His step from NASA into business.", "dx": "LITR", "key": false}, {"t": "His first step on the moon.", "dx": null, "key": true}, {"t": "His first step into the Gemini capsule.", "dx": "MIX", "key": false}, {"t": "His first flight in an airplane.", "dx": "MIX", "key": false}]},
{"q": 20826, "quiz": 1786, "obj": "P3.COMPARE_CHAR", "kind": "mcq", "was": "sentence", "body": "On Apollo 11, how was the job of Collins different from the job of Armstrong and Aldrin?", "why": "المقارنة في عمل كلٍّ منهم: «Armstrong and Aldrin landed on the moon in the lunar lander named Eagle.» و«Collins stayed in orbit around the moon in the Apollo capsule.»", "opts": [{"t": "Collins stayed in orbit, but they landed on the moon.", "dx": null, "key": true}, {"t": "Collins flew the Eagle, but they flew the Agena.", "dx": "MIX", "key": false}, {"t": "Collins landed on the moon, but they stayed in orbit.", "dx": "REV", "key": false}, {"t": "Collins collected rock samples, but they stayed in the lander.", "dx": "MIX", "key": false}]},
{"q": 20827, "quiz": 1786, "obj": "P3.CHANGE", "kind": "mcq", "was": "sentence", "body": "How did Armstrong's work change after he retired from NASA?", "why": "التغيّر بعد التقاعد: «Neil Armstrong retired from NASA the year after Apollo 11.» ثم «Armstrong was a professor at the University of Cincinnati from 1971 to 1979.»", "opts": [{"t": "He left his research and went to high school in Ohio.", "dx": "MIX", "key": false}, {"t": "He left the university and joined the Navy as a pilot.", "dx": "MIX", "key": false}, {"t": "He stopped his classes and became an astronaut.", "dx": "REV", "key": false}, {"t": "He stopped his work in space and taught at a university.", "dx": null, "key": true}]},
{"q": 20828, "quiz": 1786, "obj": "P4.SUFFICIENT", "kind": "mcq", "was": "judge", "body": "On Gemini 8, the crew docked two vehicles in space for the first time. Does this show a good mission from start to end?", "why": "الالتحام وحده لا يكفي للحكم على الرحلة كلها، فبعده: «After docking, the Gemini had a thruster problem. The capsule started spinning, and the mission ended early.»", "opts": [{"t": "Yes. The crew landed on the moon after docking.", "dx": "MIX", "key": false}, {"t": "No. The Gemini did not dock with the Agena.", "dx": "REV", "key": false}, {"t": "Yes. The crew had no problems after docking.", "dx": "REV", "key": false}, {"t": "No. A thruster problem ended the mission early.", "dx": null, "key": true}]},
{"q": 20919, "quiz": 1802, "obj": "P1.COMPETITOR", "kind": "mcq", "was": "sentence", "body": "India has a hyperloop project. What are its two cities?", "why": "في النص مدن عدّة تتنافس، والمطلوب مسار المشروع: «India is already working on a hyperloop project. It will run from Mumbai to Pune.»", "opts": [{"t": "Mumbai and Pune.", "dx": null, "key": true}, {"t": "Mumbai and Chennai.", "dx": "MIX", "key": false}, {"t": "Chennai and Bengaluru.", "dx": "MIX", "key": false}, {"t": "Delhi and Washington.", "dx": "MIX", "key": false}]},
{"q": 20920, "quiz": 1802, "obj": "P2.WORD_CONTEXT", "kind": "mcq", "was": "sentence", "body": "Vishnu reads the word \"Hyperloop\" in the newspaper. What is the Hyperloop?", "why": "المعنى من شرح فيشنو بعد الكلمة: «It’s a system with small vehicles called pods that will carry people through long, massive vacuum tubes.»", "opts": [{"t": "A fast train between islands in Japan.", "dx": "MIX", "key": false}, {"t": "A rocket for trips to outer space.", "dx": "MIX", "key": false}, {"t": "A system of pods in long vacuum tubes.", "dx": null, "key": true}, {"t": "A magic carpet from an old story.", "dx": "LITR", "key": false}]},
{"q": 20921, "quiz": 1802, "obj": "P2.ACROSS_PARA", "kind": "mcq", "was": "sentence", "body": "Rahul asks, \"But how?\" How can the pods go so fast?", "why": "السؤال في آخر فقرة وجوابه في أول التالية: «“But how?” asked a puzzled Rahul.» ثم «With hardly any air resistance or friction to slow them down in vacuum, the pods can whizz through the tubes.»", "opts": [{"t": "The tubes have solar panels on the roof.", "dx": "TASK", "key": false}, {"t": "The pods run on steam like the first trains.", "dx": "MIX", "key": false}, {"t": "The tubes have almost no air or friction inside.", "dx": null, "key": true}, {"t": "The pods have the engine of a plane.", "dx": "MIX", "key": false}]},
{"q": 20922, "quiz": 1802, "obj": "P3.MAIN_PARA", "kind": "mcq", "was": "sentence", "body": "Read the paragraph that starts with \"Hyperloop, the dream transport\". What is this paragraph about?", "why": "فكرة الفقرة في جملتها: «It is expected to be environment-friendly since the tubes can have solar panels on the roof, allowing for a clean and self-powering system.»", "opts": [{"t": "The dream of Vishnu about a trip in a pod.", "dx": "MIX", "key": false}, {"t": "The hyperloop can be faster than a bullet train.", "dx": "TASK", "key": false}, {"t": "The hyperloop can be good for the environment.", "dx": null, "key": true}, {"t": "The safety tests for the hyperloop are not over.", "dx": "TASK", "key": false}]},
{"q": 20923, "quiz": 1802, "obj": "P4.FIT", "kind": "mcq", "was": "sentence", "body": "The paragraph at the end is about dreams and great inventions. Is it a good end for the story of Vishnu?", "why": "الخاتمة توافق القصة: فيشنو حالم «Little Vishnu was a dreamer.» ويتمنّى «How I wish I had a magic carpet,» ثم يقرأ «Hyperloop: the modern day magic carpet».", "opts": [{"t": "Yes. Vishnu dreams of fast travel, and the hyperloop is an idea like his dream.", "dx": null, "key": true}, {"t": "Yes. Vishnu makes a hyperloop in his room at the end.", "dx": "JUMP", "key": false}, {"t": "No. Vishnu never dreams of anything in the story.", "dx": "REV", "key": false}, {"t": "No. The story has no new inventions for travel in it.", "dx": "REV", "key": false}]}
]$spec$::jsonb;
  e jsonb; o jsonb; r record;
  v_q bigint; v_obj bigint; v_id bigint; v_key bigint; v_dx jsonb; i int; n int;
  n_done int := 0; n_skip int := 0;
begin
  /* ── الحرّاس: كلُّ سؤالٍ في اختباره، من مكتبة المادّة ٧، وما يتحوّل بلا إجابة ── */
  for r in select (x->>'q')::bigint q, (x->>'quiz')::bigint quiz from jsonb_array_elements(spec) x loop
    if not exists (select 1 from questions qq join items it on it.quiz_id = qq.quiz_id join lessons l on l.id = it.lesson_id
                    join courses c on c.id = l.course_id
                    where qq.id = r.q and qq.quiz_id = r.quiz and c.subject_id = 7 and qq.retired_at is null) then
      raise exception 'السؤال % ليس في الاختبار % من مكتبة المادّة ٧', r.q, r.quiz;
    end if;
  end loop;
  select count(*) into n from answers a
   where a.question_id in (select (x->>'q')::bigint from jsonb_array_elements(spec) x where x->>'kind' <> 'relabel');
  if n > 0 then raise exception 'على الأسئلة % إجابة — لا يُحوَّل سؤالٌ أجاب عنه أحد', n; end if;

  for e in select * from jsonb_array_elements(spec) loop
    v_q := (e->>'q')::bigint;
    select kind, body, objective_id into r from questions where id = v_q;
    select id into strict v_obj from objectives where subject_id = 7 and code = e->>'obj';

    if e->>'kind' = 'relabel' then
      if r.objective_id is distinct from v_obj then update questions set objective_id = v_obj where id = v_q; n_done := n_done + 1;
      else n_skip := n_skip + 1; end if;
      continue;
    end if;

    if r.kind = e->>'kind' and r.body = e->>'body' then n_skip := n_skip + 1; continue; end if;
    if r.kind <> e->>'was' then raise exception 'السؤال % نمطُه % لا %', v_q, r.kind, e->>'was'; end if;

    update question_keys set correct_id = null, correct_ids = null where question_id = v_q;
    delete from options where question_id = v_q;

    if e->>'kind' = 'mcq' then
      v_key := null; v_dx := '{}'::jsonb; i := 0;
      for o in select * from jsonb_array_elements(e->'opts') loop
        i := i + 1;
        insert into options (question_id, position, body) values (v_q, i, o->>'t') returning id into v_id;
        if (o->>'key')::boolean then v_key := v_id;
        elsif o->>'dx' is not null then v_dx := v_dx || jsonb_build_object(v_id::text, o->>'dx'); end if;
      end loop;
      if v_key is null then raise exception 'السؤال % بلا مفتاح', v_q; end if;
      update questions set kind = 'mcq', body = e->>'body', objective_id = v_obj where id = v_q;
      update question_keys set correct_id = v_key, correct_ids = null, accept = null, bank = null, wrong_map = null,
             dx_map = v_dx, explanation = e->>'why' where question_id = v_q;
    else   -- matching
      i := 0;
      for o in select * from jsonb_array_elements(e->'prompts') loop
        i := i + 1;
        insert into options (question_id, position, body, item_key) values (v_q, i, o->>'t', o->>'k');
      end loop;
      update questions set kind = 'matching', body = e->>'body', objective_id = v_obj, points = i where id = v_q;
      update question_keys set correct_id = null, correct_ids = null, wrong_map = null, dx_map = '{}'::jsonb,
             bank = e->'bank', accept = jsonb_build_object('pairs', e->'pairs'), explanation = e->>'why' where question_id = v_q;
    end if;
    get diagnostics n = row_count;
    if n <> 1 then raise exception 'السؤال % بلا سطر مفتاح', v_q; end if;
    n_done := n_done + 1;
  end loop;

  if n_done + n_skip <> 44 then raise exception 'عُدِّل % وتُخطّي % والمنتظر 44', n_done, n_skip; end if;
  raise notice '258: عُدِّل % سؤالاً · تُخطّي %', n_done, n_skip;
end $$;

insert into public.sql_log (n, title, applied_at)
values ('258', 'مكتبة بيان · المستوى الحادي عشر (الدفعة الثانية): أسئلةُ الضغط والحكم تصير اختياراً من متعدّد', now())
on conflict (n) do update set applied_at = now();
